// Banco de preguntas WKF Jul 2026 — generado desde los xlsx de Socrative
const QUESTIONS = [{"id": "kata-001", "m": "kata", "en": "Kata team members must all wear the same brand of Karate Gi.", "es": "Los miembros del equipo de Kata tienen que llevar todos la misma marca de Karate Gi.", "a": false}, {"id": "kata-002", "m": "kata", "en": "The total time allowed for the Kata and BUNKAI demonstration combined is six minutes.", "es": "El tiempo total permitido para la demostración combinada de Kata y BUNKAI es de seis minutos.", "a": false}, {"id": "kata-003", "m": "kata", "en": "In Kata competition slight variations as taught by the contestant's style (Ryuha) are permitted.", "es": "En la competición de Kata se permiten ligeras variaciones según el estilo del competidor (Ryu-ha).", "a": true}, {"id": "kata-004", "m": "kata", "en": "Glasses are forbidden in Kata competition.", "es": "Gafas están prohibidas durante la ejecución de Kata.", "a": true}, {"id": "kata-005", "m": "kata", "en": "Only one discreet rubber band on a single ponytail is permitted.", "es": "Solo se permite una goma elástica discreta en una sola coleta.", "a": false}, {"id": "kata-006", "m": "kata", "en": "Kata competition can be organized in several formats.", "es": "La competición de Kata puede organizarse en varios formatos.", "a": true}, {"id": "kata-007", "m": "kata", "en": "In all competition formats, the number of Athletes cannot exceed 8.", "es": "En todos los formatos de competición, el número de atletas no puede exceder de 8.", "a": false}, {"id": "kata-008", "m": "kata", "en": "Team matches consist of competition between teams of 3 or 4 Athletes of which 3 compete at the time.", "es": "Las pruebas por equipos consisten en una competición entre equipos formados por 3 o 4 atletas, de los cuales compiten 3 a la vez.", "a": true}, {"id": "kata-009", "m": "kata", "en": "Conformance is a consistency in the performance of the Kihon in the Kata.", "es": "La conformidad es la coherencia en la ejecución de Kihon dentro del Kata.", "a": true}, {"id": "kata-010", "m": "kata", "en": "Should there be any discrepancy between the number and the name of the Kata registered for performance, the name, as per the official WKF Kata list will prevail.", "es": "En caso de que haya alguna discrepancia entre el número y el nombre del Kata inscrito para su ejecución, prevalecerá el nombre que figure en la lista oficial de Katas de la WKF.", "a": false}, {"id": "kata-011", "m": "kata", "en": "Giving a command to start and finish the Kata by a team member is not considered to be an external cue.", "es": "El hecho de que un miembro del equipo dé la orden de comenzar y terminar el Kata no se considera una señal externa.", "a": false}, {"id": "kata-012", "m": "kata", "en": "The mats must form a uniform coloured surface for Kata competition.", "es": "Las colchonetas deben formar una superficie de color uniforme para las competiciones de Kata.", "a": true}, {"id": "kata-013", "m": "kata", "en": "Judges should look for correct Kihon of the Athlete's style (Ryu-ha) being demonstrated.", "es": "Los jueces deben fijarse en que el kihon que se está demostrando sea correcto según el estilo (Ryu-ha) del atleta.", "a": true}, {"id": "kata-014", "m": "kata", "en": "The panel of Judges can be changed for any single round.", "es": "El panel de jueces puede ser cambiado para cualquier ronda individual.", "a": true}, {"id": "kata-015", "m": "kata", "en": "The total time allowed for the Kata & BUNKAI demonstration combined, is 5 minutes.", "es": "El tiempo total permitido para la demostración de Kata y BUNKAI, en conjunto, es de 5 minutos.", "a": true}, {"id": "kata-016", "m": "kata", "en": "In Kata competition the sleeves of the Karate Gi jacket cannot be rolled up.", "es": "En la competición de Kata, las mangas de la chaqueta de Karate Gi no pueden estar remangadas.", "a": true}, {"id": "kata-017", "m": "kata", "en": "It is the responsibility of the Coach or Athlete to notify the name and the number of the Kata to the runner prior to each round.", "es": "Es responsabilidad del entrenador o del atleta comunicar al runner el nombre y el número del Kata antes de cada ronda.", "a": true}, {"id": "kata-018", "m": "kata", "en": "The number of Judges per panel can be reduced to five for any competition.", "es": "El número de jueces por panel podrá reducirse a cinco en cualquier competición.", "a": false}, {"id": "kata-019", "m": "kata", "en": "A previously performed Kata can be repeated only if used as tiebreaker.", "es": "Un kata ya realizado solo podrá repetirse si se utiliza para desempatar.", "a": false}, {"id": "kata-020", "m": "kata", "en": "The Karate Gi trousers can be slightly shorter so as to only cover half of the shin.", "es": "Los pantalones del Karate Gi pueden ser ligeramente más cortos, de modo que solo cubran la mitad de la espinilla.", "a": false}, {"id": "kata-021", "m": "kata", "en": "Incorrect Kiai is a foul.", "es": "Un Kiai incorrecto se considera una falta.", "a": true}, {"id": "kata-022", "m": "kata", "en": "In Para Karate if there are 3 or less Athletes a single Kata is performed to determine 1st through 3rd place.", "es": "En Para Karate, el caso de que haya 3 atletas o menos se realizará un solo Kata para determinar los puestos del 1º al 3º.", "a": false}, {"id": "kata-023", "m": "kata", "en": "The Judges of a Kata bout cannot have the same nationality as either of the Athletes.", "es": "Los jueces de un combate de Kata no pueden tener la misma nacionalidad que ninguno de los atletas.", "a": true}, {"id": "kata-024", "m": "kata", "en": "Although ribbons and other decorations for the hair are not allowed in Kumite, they are permissible in Kata.", "es": "Aunque en Kumite no se permiten las cintas ni otros adornos para el pelo, sí están permitidos en Kata.", "a": false}, {"id": "kata-025", "m": "kata", "en": "In the bouts for medals in Team Kata competition, teams will perform a demonstration of the meaning of the Kata (BUNKAI).", "es": "En los encuentros por medallas en la competición de Kata por equipos, éstos realizarán una demostración del significado del Kata (BUNKAI).", "a": true}, {"id": "kata-026", "m": "kata", "en": "It is not possible to repeat a Kata in the Round-robin elimination system.", "es": "En el sistema de Round-robin eliminación no es posible repetir un Kata.", "a": false}, {"id": "kata-027", "m": "kata", "en": "In all competitions formats, the number of Judges can be reduced to 3.", "es": "En todas las modalidades de competición, el número de jueces puede reducirse a tres.", "a": false}, {"id": "kata-028", "m": "kata", "en": "Any Kata can be performed in the medal round, unless already performed twice.", "es": "En la ronda de medallas se puede ejecutar cualquier Kata, siempre que no se haya ejecutado ya dos veces.", "a": true}, {"id": "kata-029", "m": "kata", "en": "If an already qualified individual Athlete or Team is disqualified for misconduct (SHIKKAKU) at the conclusion of the Round-robin phase, their scheduled opponent in the first round of the elimination phase shall advance to the next round by bye (“walkover”).", "es": "Si un atleta individual o un equipo ya clasificado es descalificado por conducta indebida (SHIKKAKU) al término de la fase de Round-robin, su rival previsto en la primera ronda de la fase eliminatoria pasará a la siguiente ronda por incomparecencia («walkover»).", "a": true}, {"id": "kata-030", "m": "kata", "en": "Female Athletes must wear a plain white T-shirt beneath the Karate Gi jacket.", "es": "Las atletas deben llevar una camiseta blanca lisa debajo de la chaqueta del Karate Gi.", "a": false}, {"id": "kata-031", "m": "kata", "en": "Female Athletes can, if they want, wear a plain white T-shirt beneath the Karate Gi jacket.", "es": "Las atletas pueden, si lo desean, llevar una camiseta blanca lisa debajo de la chaqueta del Karate Gi.", "a": true}, {"id": "kata-032", "m": "kata", "en": "The wearing of unauthorised apparel, clothing or equipment is forbidden.", "es": "Queda prohibido llevar prendas, ropa o equipamiento no autorizados.", "a": true}, {"id": "kata-033", "m": "kata", "en": "A discreet rubber band or ponytail retainer is permitted in Kata competition.", "es": "En la competición de Kata se permite llevar una goma de pelo discreta.", "a": true}, {"id": "kata-034", "m": "kata", "en": "The matted Kumite areas are not suitable for Kata competition.", "es": "Las áreas de Kumité con colchonetas no son adecuadas para la competición de Kata.", "a": false}, {"id": "kata-035", "m": "kata", "en": "The Karate Gi jacket can be removed during the performance of Kata.", "es": "La chaqueta del Karate Gi puede quitarse durante la ejecución del Kata.", "a": false}, {"id": "kata-036", "m": "kata", "en": "Any theatrics must be considered very serious fouls by the Judges – on the same level as one would penalize a major loss of balance.", "es": "Los jueces deben considerar cualquier teatralidad como una falta muy grave, al mismo nivel que se sancionaría una pérdida grave del equilibrio.", "a": true}, {"id": "kata-037", "m": "kata", "en": "Variations as taught by the Athlete’s style (Ryu-ha) of Karate will not be permitted.", "es": "No se permitirán las variaciones del estilo de Karate del atleta (Ryu-ha).", "a": false}, {"id": "kata-038", "m": "kata", "en": "The runner must be notified of the choice of Kata prior to each round.", "es": "El runner debe ser notificado de la elección del Kata antes de cada ronda.", "a": true}, {"id": "kata-039", "m": "kata", "en": "A Team which does not perform the bow at the completion of the BUNKAI performance will be disqualified.", "es": "El equipo que no realice el saludo al finalizar la ejecución del BUNKAI será descalificado.", "a": true}, {"id": "kata-040", "m": "kata", "en": "The number of Kata required is dependent on the number of individual Athletes or Teams entered.", "es": "El número de Kata requeridos depende del número de atletas individuales o equipos inscritos.", "a": true}, {"id": "kata-041", "m": "kata", "en": "An Athlete who received SHIKKAKU can still be awarded a medal.", "es": "Un atleta al que se le haya impuesto un SHIKKAKU puede todavía recibir una medalla.", "a": false}, {"id": "kata-042", "m": "kata", "en": "In assessing the performance of an Athlete or team the Judges will evaluate the performance based on all criteria.", "es": "Al evaluar la actuación de un atleta o equipo, los jueces evaluarán la actuación basándose en todos los criterios.", "a": true}, {"id": "kata-043", "m": "kata", "en": "There are no specific deviations for those under 14 years of age from the standard rules, but a limitation to the Kata list to less advanced Kata can be used.", "es": "No hay excepciones específicas a las normas estándar para los menores de 14 años, pero se puede limitar la lista de Katas a aquellos menos avanzados.", "a": true}, {"id": "kata-044", "m": "kata", "en": "Causing injury by lack of controlled technique during BUNKAI is considered a foul.", "es": "Causar una lesión por falta de técnica de control durante el BUNKAI se considera falta.", "a": true}, {"id": "kata-045", "m": "kata", "en": "For medal bouts, one of the Judges can have the same nationality as the Athletes.", "es": "En las finales por las medallas, uno de los jueces puede ser de la misma nacionalidad que los deportistas.", "a": false}, {"id": "kata-046", "m": "kata", "en": "Performances are given a score using a scale from 5.0 to 10.0 in increments of 0.1.", "es": "Las actuaciones reciben una puntuación utilizando una escala de 5,0 a 10,0 en incrementos de 0,1.", "a": true}, {"id": "kata-047", "m": "kata", "en": "A coin toss is the first choice to resolve ties.", "es": "El lanzamiento de moneda es la primera opción para resolver empates.", "a": false}, {"id": "kata-048", "m": "kata", "en": "There are 6 criteria to resolve a tie in Round-robin elimination system with 4 Athletes.", "es": "Hay 6 formas de resolver un empate en el sistema de eliminación Round-robin con 4 atletas.", "a": false}, {"id": "kata-049", "m": "kata", "en": "Strength is one of the criteria of evaluation.", "es": "La fuerza es uno de los criterios de evaluación.", "a": true}, {"id": "kata-050", "m": "kata", "en": "There are 6 criteria to resolve a tie when having elimination system with 8 Athletes.", "es": "Hay 6 criterios de resolver un empate en un sistema de eliminación con 8 atletas.", "a": false}, {"id": "kata-051", "m": "kata", "en": "There are 10 criteria for Kata evaluation.", "es": "Existen 10 criterios para la evaluación del Kata.", "a": true}, {"id": "kata-052", "m": "kata", "en": "Transitional movement is one of the criteria for evaluation for Kata performance but not for BUNKAI.", "es": "El movimiento de transición es uno de los criterios de evaluación para la ejecución de Kata, pero no para BUNKAI.", "a": false}, {"id": "kata-053", "m": "kata", "en": "In BUNKAI performance, transitional movements and control are part of the evaluation.", "es": "En la ejecución de BUNKAI, los movimientos de transición y el control son parte de la evaluación.", "a": true}, {"id": "kata-054", "m": "kata", "en": "Strength, speed and balance are some of the criteria of evaluation for Kata and BUNKAI.", "es": "Fuerza, velocidad y equilibrio son algunos de los criterios de evaluación para Kata y BUNKAI.", "a": true}, {"id": "kata-055", "m": "kata", "en": "Simulated unconsciousness for more than 2 seconds at the time as part of the BUNKAI is considered a foul.", "es": "Simular estar inconsciente durante más de 2 segundos seguidos como parte del BUNKAI se considera una falta.", "a": true}, {"id": "kata-056", "m": "kata", "en": "BUNKAI is to be given equal importance as the Kata itself.", "es": "El BUNKAI debe recibir la misma importancia que el propio Kata.", "a": true}, {"id": "kata-057", "m": "kata", "en": "Excessive bowing before starting the performance is considered a foul.", "es": "Hacerse una reverencia excesiva antes de comenzar la actuación se considera una falta.", "a": true}, {"id": "kata-058", "m": "kata", "en": "Causing injury by lack of controlled technique during BUNKAI is a disqualification.", "es": "Causar lesiones por falta de control en la técnica durante el BUNKAI es una descalificación.", "a": false}, {"id": "kata-059", "m": "kata", "en": "Not announcing the Kata is not considered as disqualification.", "es": "El hecho de no anunciar el Kata no se considera motivo de descalificación.", "a": false}, {"id": "kata-060", "m": "kata", "en": "Performing the wrong Kata or announcing the wrong Kata leads to disqualification.", "es": "Realizar un Kata incorrecto o anunciar un Kata incorrecto conlleva la descalificación.", "a": true}, {"id": "kata-061", "m": "kata", "en": "Stamping the feet, slapping the chest, arms, or Karate Gi, will be taken into account by the Judges when arriving at a decision.", "es": "Los jueces tendrán en cuenta los golpes con los pies, las palmadas en el pecho, los brazos o el Karate Gi a la hora de tomar una decisión.", "a": true}, {"id": "kata-062", "m": "kata", "en": "An Athlete will not be disqualified for a distinct pause or stop in the performance for several seconds.", "es": "No se descalificará a un atleta por una pausa o interrupción evidente en la actuación que dure varios segundos.", "a": false}, {"id": "kata-063", "m": "kata", "en": "BUNKAI is not to be given equal importance as the Kata itself.", "es": "No se debe dar al BUNKAI la misma importancia que al propio Kata.", "a": false}, {"id": "kata-064", "m": "kata", "en": "Kata must start facing the Judges.", "es": "El Kata debe comenzar de cara a los jueces.", "a": true}, {"id": "kata-065", "m": "kata", "en": "The use of audible cues from any other person, including other team members is considered a foul.", "es": "El uso de señales acústicas por parte de cualquier otra persona, incluidos los demás miembros del equipo, se considera una falta.", "a": true}, {"id": "kata-066", "m": "kata", "en": "If the Athlete’s belt falls off during the performance of Kata, the Athlete will be disqualified.", "es": "Si el cinturón del atleta se cae durante la ejecución del Kata, el atleta será descalificado.", "a": true}, {"id": "kata-067", "m": "kata", "en": "Failure to follow the instructions of the Chief Judge or other misconduct is considered a foul.", "es": "El incumplimiento de las instrucciones del juez principal u otra conducta indebida se considera una falta.", "a": false}, {"id": "kata-068", "m": "kata", "en": "Failure to follow the instructions of the Chief Judge or other misconduct leads to disqualification.", "es": "El incumplimiento de las instrucciones del juez principal u otra conducta indebida dará lugar a la descalificación.", "a": true}, {"id": "kata-069", "m": "kata", "en": "Exceeding the total time limit of 5 minutes duration for Kata and BUNKAI is considered a foul.", "es": "Exceder el tiempo límite total de 5 minutos de duración para Kata y BUNKAI se considera una falta.", "a": false}, {"id": "kata-070", "m": "kata", "en": "In Team Kata, all three team members must start and finish the Kata facing in the same direction and towards the Judges.", "es": "En Kata por equipos, los tres miembros del equipo deben empezar y terminar el Kata mirando en la misma dirección y hacia los jueces.", "a": false}, {"id": "kata-071", "m": "kata", "en": "Kata performance must be realistic in fighting terms and display concentration, power, and potential impact in its techniques.", "es": "La ejecución del Kata debe ser realista en términos de combate y mostrar concentración, potencia e impacto potencial en sus técnicas.", "a": true}, {"id": "kata-072", "m": "kata", "en": "Causing injury by lack of controlled technique during BUNKAI is not considered a foul.", "es": "Causar lesiones por falta de control en la técnica durante el BUNKAI no se considera una falta.", "a": false}, {"id": "kata-073", "m": "kata", "en": "Minor loss of balance must not be considered in the evaluation of the Kata performance.", "es": "La pérdida menor de equilibrio no debe ser considerada en la evaluación de la ejecución del Kata.", "a": false}, {"id": "kata-074", "m": "kata", "en": "Exceeding the total time limit of 5 minutes duration for Kata and BUNKAI leads to disqualification.", "es": "Exceder el tiempo límite total de 5 minutos de duración para Kata y BUNKAI se considera una descalificación.", "a": true}, {"id": "kata-075", "m": "kata", "en": "Kata performance must demonstrate strength, balance, and speed.", "es": "La ejecución del Kata debe demostrar fuerza, equilibrio y velocidad.", "a": true}, {"id": "kata-076", "m": "kata", "en": "Minor loss of balance must be considered in the evaluation of the Kata performance.", "es": "En la evaluación de la ejecución del Kata se debe tener en cuenta cualquier pequeña pérdida de equilibrio.", "a": true}, {"id": "kata-077", "m": "kata", "en": "Asynchronous movement, such as delivering a technique before the body transition is completed is considered a foul.", "es": "Los movimientos asincrónicos, como ejecutar una técnica antes de que se haya completado la transición corporal, se consideran una falta.", "a": true}, {"id": "kata-078", "m": "kata", "en": "Inappropriate exhalation will be taken into account by the Judges when arriving at a decision.", "es": "La exhalación inapropiada será tenida en cuenta por los jueces a la hora de tomar una decisión.", "a": true}, {"id": "kata-079", "m": "kata", "en": "In Team Kata, failing to do synchronised movements is not considered a foul.", "es": "En el Kata por equipos, no realizar los movimientos sincronizados no se considera una falta.", "a": false}, {"id": "kata-080", "m": "kata", "en": "Performing a movement in an incorrect or incomplete manner is considered a foul.", "es": "Realizar un movimiento de forma incorrecta o incompleta se considera una falta.", "a": true}, {"id": "kata-081", "m": "kata", "en": "Time wasting, including prolonged marching, excessive bowing or prolonged pause before starting the performance is considered a foul.", "es": "Se considera una falta cualquier pérdida de tiempo, como las marchas prolongadas, las reverencias excesivas o las pausas prolongadas antes de comenzar la actuación.", "a": true}, {"id": "kata-082", "m": "kata", "en": "Stamping the feet, slapping the chest, arms, or Karate Gi, are theatrics.", "es": "Dar pisotones o palmadas en el pecho, brazos o Karate Gi, son la teatralidad.", "a": true}, {"id": "kata-083", "m": "kata", "en": "The use of theatrics is not considered a foul.", "es": "El uso de teatralidad no se considera una falta.", "a": false}, {"id": "kata-084", "m": "kata", "en": "Inappropriate exhalation is not considered theatrics.", "es": "La exhalación inapropiada no es consisderada teatralidad.", "a": false}, {"id": "kata-085", "m": "kata", "en": "Failure to fully execute a block or punching off target is considered a foul.", "es": "No ejecutar completamente un bloqueo o golpear fuera del objetivo se considera una falta.", "a": true}, {"id": "kata-086", "m": "kata", "en": "Causing injury by lack of controlled technique during BUNKAI is allowed.", "es": "Causar lesión por falta del control durante el BUNKAI está permitido.", "a": false}, {"id": "kata-087", "m": "kata", "en": "The members of the team must demonstrate competence in all aspects of the Kata performance, as well as synchronisation.", "es": "Los miembros del equipo deben demostrar competencia en todos los aspectos de la ejecución del Kata, así como sincronización.", "a": true}, {"id": "kata-088", "m": "kata", "en": "Commands to start and stop the performance will be taken into account by the Judges when arriving at a decision.", "es": "Los jueces tendrán en cuenta las órdenes de inicio y finalización de la ejecución a la hora de tomar una decisión.", "a": true}, {"id": "kata-089", "m": "kata", "en": "It is the responsibility of the President of the National Federation to ensure that the Kata as notified to the runner is appropriate for that particular round.", "es": "Es responsabilidad del Presidente de la Federación Nacional asegurarse de que el Kata notificado a el runner es apropiado para esa ronda en particular.", "a": false}, {"id": "kata-090", "m": "kata", "en": "While performing BUNKAI, after being downed the Athlete should either raise to one knee or stand up within 2 seconds.", "es": "Al realizar BUNKAI, después de ser derribado, el atleta debe levantarse sobre una rodilla o ponerse de pie antes de 2 segundos.", "a": true}, {"id": "kata-091", "m": "kata", "en": "Omitting or adding movements - or otherwise substantially change the performance from its original form is a disqualification.", "es": "Omitir o añadir movimientos o cambiar sustancialmente la ejecución de su forma original es una descalificación.", "a": true}, {"id": "kata-092", "m": "kata", "en": "Excessive celebration and political or religious demonstrations is considered as disqualification for Kumite but not for Kata.", "es": "La celebración excesiva y las manifestaciones políticas o religiosas se consideran descalificación para Kumité, pero no para Kata.", "a": false}, {"id": "kata-093", "m": "kata", "en": "Only Kata from the WKF official Kata list can be performed.", "es": "Solo se pueden ejecutar los Katas de la lista oficial de Katas de WKF.", "a": true}, {"id": "kata-094", "m": "kata", "en": "A team which does not perform the bow at the beginning and completion of the performance will be disqualified.", "es": "El equipo que no realice el saludo al principio y al final de la actuación será descalificado.", "a": true}, {"id": "kata-095", "m": "kata", "en": "The use of traditional weapons, ancillary equipment or additional apparel is allowed.", "es": "Se permite el uso de armas tradicionales, equipo auxiliar o indumentaria adicional.", "a": false}, {"id": "kata-096", "m": "kata", "en": "The performance in individual Kata is evaluated from the bow starting the Kata until the bow ending the Kata.", "es": "La ejecución en Kata individual se evalúa desde el saludo que inicia el Kata hasta el saludo que lo finaliza.", "a": true}, {"id": "kata-097", "m": "kata", "en": "Belt coming loose to the extent that it is coming off the hips during the performance is a foul.", "es": "El cinturón suelto hasta el punto de salirse de las caderas durante la ejecución es una falta.", "a": true}, {"id": "kata-098", "m": "kata", "en": "Belt coming loose to the extent that it is coming off the hips during the performance is a disqualification.", "es": "El cinturón suelto hasta el punto de salirse de las caderas durante la ejecución es una descalificación.", "a": false}, {"id": "kata-099", "m": "kata", "en": "After the bow the Athlete must clearly announce the name of the Kata that is to be performed and then start the performance.", "es": "Después del saludo, el atleta debe anunciar claramente el nombre del Kata que se va a ejecutar y, a continuación, comenzar la ejecución.", "a": true}, {"id": "kata-100", "m": "kata", "en": "There are 9 criteria in Kata evaluation.", "es": "Hay 9 criterios en la evaluación de Kata.", "a": false}, {"id": "kata-101", "m": "kata", "en": "Although performing a scissor takedown technique (KANI BASAMI) to the neck area during BUNKAI is prohibited, a scissor takedown to the body is permitted.", "es": "Aunque está prohibido realizar una técnica de derribo en tijera (KANI BASAMI) a la zona del cuello al ejecutar BUNKAI, está permitido un derribo en tijera al cuerpo.", "a": true}, {"id": "kata-102", "m": "kata", "en": "Performing a scissor takedown technique (KANI BASAMI) to the neck area during BUNKAI is not prohibited.", "es": "No está prohibido realizar una técnica de tijera (KANI BASAMI) en la zona del cuello en BUNKAI.", "a": false}, {"id": "kata-103", "m": "kata", "en": "Theatrics must be considered very serious fouls by the Judges in their evaluation of the performance of the Kata.", "es": "La teatralidad debe ser considerada una falta muy grave por los jueces en su evaluación de la ejecución del Kata.", "a": true}, {"id": "kata-104", "m": "kata", "en": "The protest can be submitted to a representative of the Appeals Jury by the Coach.", "es": "La protesta puede ser presentada a un representante del Jurado de Apelación por el entrenador.", "a": false}, {"id": "kata-105", "m": "kata", "en": "It is the responsibility of the Tatami Manager receiving the protest to gather the Appeals Jury and deposit the protest sum with WKF for any declined protest.", "es": "Es la responsabilidad del Tatami Manager que recibe la protesta reunir al Jurado de Apelación y depositar la suma de la protesta a WKF por cualquier protesta rechazada.", "a": true}, {"id": "kata-106", "m": "kata", "en": "Each of the three members of the Appeals Jury is obliged to give their verdict as to the validity of the protest. Abstentions are not acceptable.", "es": "Cada uno de los tres miembros del Jurado de Apelación está obligado a dar su veredicto sobre la validez de la protesta. Las abstenciones no son aceptables.", "a": true}, {"id": "kata-107", "m": "kata", "en": "In Para Karate, advertising on the backrest of the wheelchairs is allowed.", "es": "En Para Karate, la publicidad en las sillas de ruedas puede colocarse en el respaldo.", "a": false}, {"id": "kata-108", "m": "kata", "en": "If the protest is accepted, the Appeals Jury will appoint one of its members who will verbally notify the protester that the protest has been accepted.", "es": "Si la protesta es aceptada, el Jurado de Apelación designará a uno de sus miembros que notificará verbalmente al protestante que la protesta ha sido aceptada.", "a": true}, {"id": "kata-109", "m": "kata", "en": "There are three general Categories in Para Karate competitions: Visually Impaired, Intellectually Impaired and Physically Impaired.", "es": "Hay tres categorías generales en las competiciones de Para Karate: discapacidad visual, discapacidad intelectual y discapacidad física.", "a": true}, {"id": "kata-110", "m": "kata", "en": "In Para Karate competitions, prostheses, canes, crutches, and other equipment used for physical support are allowed.", "es": "En las competiciones de Para Karate, las prótesis, bastones, muletas y otros equipos utilizados para el apoyo físico están permitidos.", "a": false}, {"id": "kata-111", "m": "kata", "en": "In Para Karate, Athletes with more than one Eligible Impairment can compete in only one Sport Class per championship.", "es": "En Para Karate, los atletas con más de una discapacidad reconocida solo podrán competir en una categoría deportiva por campeonato.", "a": true}, {"id": "kata-112", "m": "kata", "en": "In Para Karate, the seven Judges will give their scores based on the assessment of the Kata performance and the level of the Athlete's impairment.", "es": "En Para Karate, los siete jueces darán sus puntuaciones basándose en la valoración de la ejecución del Kata y el nivel de discapacidad del competidor.", "a": false}, {"id": "kata-113", "m": "kata", "en": "Para Karate competitions consist of both Kata and Kumite.", "es": "Las competiciones de Para Karate consisten tanto en Kata como en Kumité.", "a": false}, {"id": "kata-114", "m": "kata", "en": "In Para Karate competitions wheelchairs with approved anti-tip castors are allowed.", "es": "En las competiciones de Para Karate las sillas de ruedas con ruedidas antivuelco approbadas están permitidas.", "a": true}, {"id": "kata-115", "m": "kata", "en": "In Para Karate a Compensation Score is allocated to Athletes in all Sport Classes in accordance with the WKF Para Karate Classification Rules.", "es": "En Para Karate se asigna una puntuación de compensación a los atletas de todas las categorías deportivas, de conformidad con las normas de clasificación de WKF para el Para Karate.", "a": false}, {"id": "kata-116", "m": "kata", "en": "In Para Karate, potential reasons for disqualification must be treated with particular care, as certain eligible impairments or underlying health conditions can influence movement patterns or behaviour during performance.", "es": "En Para Karate, hay que prestar especial atención a los posibles motivos de descalificación, ya que determinadas discapacidades o afecciones médicas subyacentes que cumplen los requisitos pueden influir en los patrones de movimiento o en el comportamiento durante la competición.", "a": true}, {"id": "kata-117", "m": "kata", "en": "All Para Karate Athletes are allowed to wear white sport shoes.", "es": "Todos los atletas de Para Karate pueden llevar calzado deportivo blanco.", "a": false}, {"id": "kata-118", "m": "kata", "en": "In Para Karate, in case of additional Classification testing, Doping Control, fire or other need for emergency evacuation, the national Coaches are directly responsible for safe removal of their Athletes.", "es": "En Para Karate, en caso de pruebas de clasificación adicionales, control antidopaje, incendio u otra necesidad de evacuación de emergencia, los entrenadores nacionales son directamente responsables de la retirada segura de sus atletas.", "a": true}, {"id": "kata-119", "m": "kata", "en": "In Para Karate, Athletes from the Intellectually Impaired category can perform the same Kata in each round.", "es": "En Para Karate, los atletas de la categoría de Discapacitados Intelectuales pueden realizar el mismo Kata en cada ronda.", "a": true}, {"id": "kata-120", "m": "kata", "en": "In Para Karate, service animals trained and certified to detect life-threatening conditions are not allowed at the external perimeter of the competition area.", "es": "En Para Karate los animales de servicio entrenados y certificados para detectar condiciones que pongan en peligro la vida no están permitidos en el perímetro exterior del área de competición.", "a": false}, {"id": "kata-121", "m": "kata", "en": "The Appeals Jury must elaborate a simple protest incident report, describing their findings and state their reason(s) for accepting or rejecting the protest.", "es": "El Jurado de Apelación debe elaborar un simple informe del incidente de protesta, describiendo sus conclusiones y exponiendo su(s) razón(es) para aceptar o rechazar la protesta.", "a": true}, {"id": "kata-122", "m": "kata", "en": "There are 100 Kata on the official WKF Kata list.", "es": "Hay 100 Katas en la lista oficial de Kata de WKF.", "a": false}, {"id": "kata-123", "m": "kata", "en": "In Para Karate resolution for ties will follow the WKF Kata Competition Rules.", "es": "En Para Karate la resolución de los empates seguirá el Reglamento de Competición de Kata de WKF.", "a": false}, {"id": "kata-124", "m": "kata", "en": "In Para Karate, therapy animals or emotional-support animals are allowed in the competition area or its perimeter.", "es": "En Para Karate, los animales de terapia o de apoyo emocional están permitidos en el área de competición o en su perímetro.", "a": false}, {"id": "kata-125", "m": "kata", "en": "In Para Karate, it is allowed for Athletes of Visually Impaired Classes to wear blindfolds with logos or markings from sponsors or manufacturers.", "es": "En Para Karate, está permitido que los atletas de la clase de discapacidad visual lleven vendas en los ojos con logotipos o marcas de patrocinadores o fabricantes.", "a": false}, {"id": "kata-126", "m": "kata", "en": "In Para Karate, the straps to fix the legs of wheelchair Athletes can be elastic.", "es": "En Para Karate, las correas para sujetar las piernas de los atletas en silla de ruedas pueden ser elásticas.", "a": false}, {"id": "kata-127", "m": "kata", "en": "In Para Karate, score compensation system by means of Extra Points, must be given by the Judges according to the influence of the Athlete's particular impairment.", "es": "En Para Karate, el sistema de compensación de puntuación mediante puntos extras debe ser aplicado por los jueces de acuerdo a la influencia que tenga la discapacidad concreta del atleta.", "a": false}, {"id": "kata-128", "m": "kata", "en": "In Para Karate there are three Sport Classes.", "es": "En Para Karate existen tres clases deportivas.", "a": false}, {"id": "kata-129", "m": "kata", "en": "In Para Karate visually impaired Athletes are divided in three categories.", "es": "En Para Karate los atletas con discapacidad visual se divide en tres categorías.", "a": false}, {"id": "kata-130", "m": "kata", "en": "In Para Karate, blindfolds are required for all visually impaired Athletes during the performance.", "es": "En Para Karate, durante la actuación, se requieren vendas para los ojos a todos los atletas con discapacidad visual.", "a": true}, {"id": "kata-131", "m": "kata", "en": "In Para Karate, intellectual impaired Athletes will perform the Kata standing up.", "es": "En Para Karate los atletas con discapacidad intelectual realizarán el Kata de pie.", "a": true}, {"id": "kata-132", "m": "kata", "en": "In Para Karate, intellectual impaired Athletes cannot repeat the Kata.", "es": "En Para Karate, los atletas con discapacidad intelectual no pueden repetir el Kata.", "a": false}, {"id": "kumite-001", "m": "kumite", "en": "Any voluntary religious headwear can be worn.", "es": "Se puede llevar cualquier tocado religioso volontario.", "a": false}, {"id": "kumite-002", "m": "kumite", "en": "The Karate Gi jacket must be more than three-quarters thigh length.", "es": "La chaqueta de Karate Gi debe tener una longitud superior a tres cuartos del muslo.", "a": false}, {"id": "kumite-003", "m": "kumite", "en": "The Karate Gi trousers must cover at least two-thirds of the shin.", "es": "Los pantalones de Karate Gi deben cubrir al menos dos tercios de la espinilla.", "a": true}, {"id": "kumite-004", "m": "kumite", "en": "The Karate Gi jacket sleeves must be no longer than the bend of the wrist.", "es": "Le manga de la chaqueta de Karate Gi no debe ser más larga que el pliegue de la muñeca.", "a": true}, {"id": "kumite-005", "m": "kumite", "en": "If an Athlete's Karate Gi jacket sleeves are too long and a suitable replacement cannot be found in time the Referee can allow him to turn them up on the inside.", "es": "Si las mangas de la chaqueta de Karate Gi de un atleta son demasiado largas y no se puede encontrar un recambio adecuado a tiempo, el árbitro puede permitirle que se las suba por dentro.", "a": false}, {"id": "kumite-006", "m": "kumite", "en": "Athletes can wear 1 or 2 discreet rubber bands on a single ponytail. Ribbons, beads and other decorations are prohibited.", "es": "Los atletas pueden llevar una o dos gomas discretas en una sola coleta. Diademas, cadenas y otros adornos están prohibidos.", "a": true}, {"id": "kumite-007", "m": "kumite", "en": "Earrings are allowed if they are covered with tape.", "es": "Los pendientes están permitidos si están cubiertos con cinta adhesiva.", "a": false}, {"id": "kumite-008", "m": "kumite", "en": "Metallic teeth braces can be worn at the Athlete's own risk if approved by the Referee and the Official Doctor.", "es": "Se pueden llevar aparatos dentales metálicos por cuenta y riesgo del atleta si lo aprueban el árbitro y el médico oficial.", "a": true}, {"id": "kumite-009", "m": "kumite", "en": "Athletes must bow properly to each other at the start and end of the bout.", "es": "Los atletas deben saludarse correctamente al comienzo y al final del combate.", "a": true}, {"id": "kumite-010", "m": "kumite", "en": "The Coach can change the team fighting order during a match.", "es": "El entrenador puede cambiar el orden de combate por equipos durante un encuentro.", "a": false}, {"id": "kumite-011", "m": "kumite", "en": "If an Athlete is injured in an individual bout the Coach can enter a replacement if he notifies the Organising Commission first.", "es": "Si un atleta se lesiona en un combate individual, el entrenador puede inscribir a un sustituto si lo notifica primero a la Comisión Organizadora.", "a": false}, {"id": "kumite-012", "m": "kumite", "en": "Each Judge must be equipped with a red and a blue flag or joysticks.", "es": "Cada juez debe estar equipado con una bandera roja y una azul o joysticks.", "a": true}, {"id": "kumite-013", "m": "kumite", "en": "If two teams have the same number of victories and points, a deciding bout will be held.", "es": "Si dos equipos tienen el mismo número de victorias y puntos, se celebrará un combate decisivo.", "a": true}, {"id": "kumite-014", "m": "kumite", "en": "The Match Supervisor (KANSA) will be equipped with only a whistle.", "es": "El Supervisor del encuentro (KANSA) estará equipado únicamente con un silbato.", "a": true}, {"id": "kumite-015", "m": "kumite", "en": "Disqualification by KIKEN means that the Athletes are disqualified from that category.", "es": "La descalificación por KIKEN significa que los atletas quedan descalificados de esa categoría.", "a": true}, {"id": "kumite-016", "m": "kumite", "en": "Heels of more than 4 cm must not be worn with the uniform.", "es": "No se podrán llevar tacones de más de 4 cm con el uniforme.", "a": true}, {"id": "kumite-017", "m": "kumite", "en": "Senior Male bouts are three minutes, and Senior Female, Cadets, and Juniors, two minutes.", "es": "Senior Male bouts are three minutes, and Senior Female, Cadets, and Juniors, two minutes.", "a": false}, {"id": "kumite-018", "m": "kumite", "en": "Kumite team members can wear any type of Karate Gi.", "es": "Los miembros del equipo de Kumite pueden usar cualquier tipo de Karate Gi.", "a": false}, {"id": "kumite-019", "m": "kumite", "en": "Different Karate Gi brands can be used for team members.", "es": "Se pueden utilizar diferentes marcas de Karate Gi para los miembros del equipo.", "a": true}, {"id": "kumite-020", "m": "kumite", "en": "An Athlete does not need to change the jacket if the ties are torn off during the bout.", "es": "Un atleta no necesita cambiar la chaqueta si los lazos se rompen durante el combate.", "a": true}, {"id": "kumite-021", "m": "kumite", "en": "Athletes can wear any white Karate Gi.", "es": "Los atletas pueden usar cualquier Karate Gi blanco.", "a": false}, {"id": "kumite-022", "m": "kumite", "en": "A fast combination of CHUDAN KERI and TSUKI each of which score in their own right will be given IPPON.", "es": "Con una combinación rápida de CHUDAN KERI y TSUKI, cada uno de los cuales puntúa correctamente, se dará IPPON.", "a": false}, {"id": "kumite-023", "m": "kumite", "en": "In Senior bouts a light \"skin touch\" to the throat does not need to result in a warning or penalty provided there is no injury.", "es": "En los encuentros Senior, un ligero toque de guante \"skin touch\" en la garganta no tiene por qué dar lugar a una advertencia o penalización, siempre que no haya una lesión.", "a": false}, {"id": "kumite-024", "m": "kumite", "en": "A kick in the groin will not result in a penalty provided the offender did not do it intentionally.", "es": "Una patada en la ingle no dará lugar a penalización siempre que el infractor no lo haya hecho intencionadamente.", "a": false}, {"id": "kumite-025", "m": "kumite", "en": "For Athletes under 14 years of age, the WKF approved protective helmet is compulsory.", "es": "Para los atletas menores de 14 años, es obligatorio el uso del casco protector homologado por la WKF.", "a": true}, {"id": "kumite-026", "m": "kumite", "en": "If SENSHU is withdrawn when it is less than 15 seconds left of the bout, no further SENSHU can be awarded to either Athlete.", "es": "Si se retira el SENSHU cuando quedan menos de 15 segundos de combate, no se podrá conceder más SENSHU a ninguno de los atletas.", "a": true}, {"id": "kumite-027", "m": "kumite", "en": "Si un atleta al que se le ha concedido SENSHU recibe una advertencia por evitar el combate cuando quedan menos de 15 segundos de combate, el atleta perderá automáticamente esta ventaja.", "es": "Si un atleta al que se le ha concedido SENSHU recibe una advertencia por evitar el combate cuando quedan menos de 15 segundos de combate, el atleta perderá automáticamente esta ventaja.", "a": true}, {"id": "kumite-028", "m": "kumite", "en": "Los tocados religiosos voluntarios deben ser aprobados por la WKF.", "es": "Los tocados religiosos voluntarios deben ser aprobados por la WKF.", "a": true}, {"id": "kumite-029", "m": "kumite", "en": "El Supervisor de Competición de la WKF o la Comisión Organizadora pueden permitir a los entrenadores usar cualquier camiseta en lugar de la chaqueta del chándal.", "es": "El Supervisor de Competición de la WKF o la Comisión Organizadora pueden permitir a los entrenadores usar cualquier camiseta en lugar de la chaqueta del chándal.", "a": false}, {"id": "kumite-030", "m": "kumite", "en": "HANSOKU CHUI si el potencial del atleta para ganar ha sido reducido por la falta del oponente.", "es": "HANSOKU CHUI si el potencial del atleta para ganar ha sido reducido por la falta del oponente.", "a": true}, {"id": "kumite-031", "m": "kumite", "en": "La tolerancia de peso admitida para hombres y mujeres es de 0,5 kg.", "es": "La tolerancia de peso admitida para hombres y mujeres es de 0,5 kg.", "a": false}, {"id": "kumite-032", "m": "kumite", "en": "HANSOKU is imposed for very serious rules infractions.", "es": "HANSOKU se impone por infracciones muy graves de las reglas.", "a": true}, {"id": "kumite-033", "m": "kumite", "en": "SHIKKAKU can only be imposed after a warning has been given.", "es": "SHIKKAKU sólo puede imponerse después de que se haya dado una advertencia.", "a": false}, {"id": "kumite-034", "m": "kumite", "en": "If an Athlete acts maliciously, SHIKKAKU and not HANSOKU is the correct penalty.", "es": "Si un atleta actúa maliciosamente, SHIKKAKU y no HANSOKU es la penalización correcta.", "a": true}, {"id": "kumite-035", "m": "kumite", "en": "If an Athlete acts maliciously, HANSOKU is the correct penalty.", "es": "Si un atleta actúa maliciosamente, HANSOKU es la penalización correcta.", "a": false}, {"id": "kumite-036", "m": "kumite", "en": "An Athlete can be given SHIKKAKU if the behaviour of the Coach or noncombatant members of the Athlete's delegation is considered to harm the prestige and honour of Karate-Do.", "es": "Se puede dar SHIKKAKU a un atleta si se considera que el comportamiento del entrenador o de los miembros no combatientes de la delegación del atleta daña el prestigio y el honor del Karate-Do.", "a": false}, {"id": "kumite-037", "m": "kumite", "en": "For individual competition, the Roundrobin system followed by quarterfinals, semifinals and final is applied.", "es": "Para la competición individual, se aplica el sistema round-robin seguido de cuartos de final, semifinales y final.", "a": false}, {"id": "kumite-038", "m": "kumite", "en": "There are five criteria to be met in determining a score.", "es": "Hay cinco criterios que deben cumplirse para determinar una puntuación.", "a": false}, {"id": "kumite-039", "m": "kumite", "en": "A male team must present a minimum of five Athletes for the initial round.", "es": "Un equipo masculino debe presentar un mínimo de cinco atletas para la ronda inicial.", "a": true}, {"id": "kumite-040", "m": "kumite", "en": "Male Kumite teams in the elimination format comprise five to seven members with five competing in the first round.", "es": "Los equipos masculinos en el formato de eliminatión se componen de cinco a siete miembros de los cuales cinco compiten en la primera ronda.", "a": true}, {"id": "kumite-041", "m": "kumite", "en": "A female team must present a minimum of two Athletes for the initial round.", "es": "Un equipo femenino debe presentar un mínimo de dos atletas para la ronda inicial.", "a": false}, {"id": "kumite-042", "m": "kumite", "en": "If the Coach continues to interfere after the first warning, the Referee will stop the bout, approach again and ask the Coach to leave the Tatami.", "es": "Si el entrenador continúa interfiriendo después de la primera advertencia, el árbitro detendrá el combate, se acercará de nuevo al entrenador y le pedirá que abandone el tatami.", "a": true}, {"id": "kumite-043", "m": "kumite", "en": "If AKA scores just as AO steps outside of the competition area, both the score and warning or penalty can be given.", "es": "Si AKA puntúa justo cuando AO sale del área de competición, se puede dar tanto el punto como la advertencia o penalización.", "a": false}, {"id": "kumite-044", "m": "kumite", "en": "If an Athlete has been physically propelled from the area, JOGAI will be given.", "es": "Si un atleta ha sido impulsado físicamente fuera del área, se dará JOGAI.", "a": false}, {"id": "kumite-045", "m": "kumite", "en": "In Premier League competition, the losers to the finalists in the quarterfinals and semifinals compete for the bronze medals.", "es": "En la competición de la Premier League, los perdedores ante los finalistas en cuartos de final y semifinales compiten por las medallas de bronce.", "a": true}, {"id": "kumite-046", "m": "kumite", "en": "In Round-robin, in cases where there is a tie between two or more Athletes in a group, having the same number of total points, the first criterion to consider is the highest World Ranking at the date of the competition.", "es": "En round-robin, en caso de que haya un empate entre dos o más atletas de un grupo que tengan el mismo número de puntos totales, el primer criterio a considerar es la clasificación mundial más alta a fecha de la competición.", "a": false}, {"id": "kumite-047", "m": "kumite", "en": "It is possible for an Athlete to be disqualified from a bout (HANSOKU) and continue the competition.", "es": "Es posible que un atleta sea descalificado de un combate (HANSOKU) y continúe la competición.", "a": true}, {"id": "kumite-048", "m": "kumite", "en": "An Athlete who scores and exits the area before the Referee calls YAME will not receive JOGAI.", "es": "Un atleta que puntué y salga del área antes de que el árbitro diga YAME, no recibirá JOGAI.", "a": true}, {"id": "kumite-049", "m": "kumite", "en": "Athletes cannot be given penalties after the time-up bell has signalled the end of a bout.", "es": "Los atletas no pueden ser penalizados después de que la señal de tiempo haya señalado el final de un combate.", "a": false}, {"id": "kumite-050", "m": "kumite", "en": "Any technique to the face, head or neck, which causes injury will be warned or penalised unless it is the recipient's own fault.", "es": "Cualquier técnica a la cara, cabeza o cuello que cause lesión será advertida o penalizada a menos que sea culpa del receptor.", "a": true}, {"id": "kumite-051", "m": "kumite", "en": "In Cadet and Junior competition JODAN techniques are allowed to make \"skin touch\" provided there is no injury.", "es": "En las competiciones Cadete y Junior, las técnicas de JODAN permiten «skin touch», siempre que no haya lesiones.", "a": true}, {"id": "kumite-052", "m": "kumite", "en": "In Senior competition a light touch is allowed for JODAN punches, and a greater tolerance is allowed for JODAN kicks.", "es": "En la competición Senior, se permite un toque ligero para las técnicas de puño JODAN y una mayor tolerancia para las patadas JODAN.", "a": false}, {"id": "kumite-053", "m": "kumite", "en": "An already qualified Athlete cannot be disqualified for misconduct (SHIKKAKU) at the end of the Roundrobin.", "es": "Un atleta ya clasificado no puede ser descalificado por mala conducta (SHIKKAKU) al final del round-robin.", "a": false}, {"id": "kumite-054", "m": "kumite", "en": "If a variation of the competition format other than described in the rules is to be applied for a particular tournament, this has to be clearly announced in the tournament bulletin.", "es": "Si se va a aplicar una variación del formato de competición distinta a la descrita en el reglamento para un torneo en particular, deberá anunciarse claramente en el boletín del torneo.", "a": true}, {"id": "kumite-055", "m": "kumite", "en": "If an Athlete has been asked before the bout starts, and confirms wearing a groin guard, and it later proves that this is not so, the Athlete will receive SHIKKAKU.", "es": "Si se le pregunta a un atleta antes de que comience el combate si lleva protector de ingle y este lo confirma, pero posteriormente se comprueba que no es así, se le impondrá una sanción de SHIKKAKU.", "a": true}, {"id": "kumite-056", "m": "kumite", "en": "When the Judges see a score, they will immediately signal it with their joystick or flag.", "es": "Cuando los jueces vean una puntuación, señalarán inmediatamente con los joysticks o las banderas.", "a": true}, {"id": "kumite-057", "m": "kumite", "en": "The Referee Panel is composed of one Tatami Manager and three Tatami Manager Assistants.", "es": "El panel arbitral está compuesto por un tatami manager y tres asistentes del tatami manager.", "a": false}, {"id": "kumite-058", "m": "kumite", "en": "The Referee Panel for each bout shall consist of one Referee, four Judges and one Match Supervisor.", "es": "El Panel de Arbitraje para cada encuentro estará compuesto por un árbitro, cuatro jueces y un supervisor del encuentro.", "a": false}, {"id": "kumite-059", "m": "kumite", "en": "If after the bout has started, an Athlete is found not to be wearing a gumshield, the Athlete will be disqualified.", "es": "Si una vez comenzado el combate se descubre que un atleta no lleva puesto el protector dental, el atleta será descalificado.", "a": false}, {"id": "kumite-060", "m": "kumite", "en": "The Referee will give all commands and make all announcements.", "es": "El árbitro dará todas las órdenes y hará todos los anuncios.", "a": true}, {"id": "kumite-061", "m": "kumite", "en": "Duration of the Kumite bout is 1.5 minutes for under 14 years.", "es": "La duración del combate de Kumite es de 1,5 minutos para menores de 14 años.", "a": true}, {"id": "kumite-062", "m": "kumite", "en": "If three Judges signal a score for AKA, the Referee must stop the bout even if he believes they are mistaken.", "es": "Si tres jueces señalan una puntuación para AKA, el árbitro debe parar el combate, incluso si cree que están equivocados.", "a": true}, {"id": "kumite-063", "m": "kumite", "en": "If two or more Judges signal a score for the same Athlete, the Referee must stop the bout.", "es": "Si dos o más jueces señalan una puntuación para el mismo atleta, el árbitro debe parar el combate.", "a": true}, {"id": "kumite-064", "m": "kumite", "en": "The timing of a bout starts when the Referee gives the signal to start and stops when the Referee calls \"YAME\" or when the time is up.", "es": "El tiempo de un combate comienza cuando el árbitro da la señal de comienzo y se detiene cuando el árbitro dice \"YAME\" o cuando se acaba el tiempo.", "a": true}, {"id": "kumite-065", "m": "kumite", "en": "The Referee Panel shall consist of one Referee, four Judges, one Match Supervisor and one Score Keeper.", "es": "El Panel de Arbitraje estará compuesto por un árbitro, cuatro jueces, un supervisor del encuentro y un anotador de puntuación.", "a": false}, {"id": "kumite-066", "m": "kumite", "en": "The Athlete's Coach is the only one allowed to make a protest.", "es": "El entrenador del atleta es el único autorizado para presentar una protesta.", "a": false}, {"id": "kumite-067", "m": "kumite", "en": "If the Referee does not hear the timeup signal, KANSA will blow the whistle.", "es": "Si el árbitro no oye la señal de finalización del tiempo, KANSA del encuentro hará sonar el silbato.", "a": false}, {"id": "kumite-068", "m": "kumite", "en": "The Athletes must only bow properly to each other at the start of the bout.", "es": "Los atletas sólo deben saludarse correctamente al comienzo del combate.", "a": false}, {"id": "kumite-069", "m": "kumite", "en": "In individual bouts an Athlete who withdraws voluntarily from the bout is declared KIKEN and an extra eight points are awarded to the opponent.", "es": "En encuentros individuales, un atleta que se retire voluntariamente del combate será declarado KIKEN y se otorgarán ocho puntos extra al oponente.", "a": false}, {"id": "kumite-070", "m": "kumite", "en": "Awareness is the state of continued commitment, which endures after the technique has landed.", "es": "La conciencia de estar a riesgo es el estado de compromiso continuo, que perdura después de que la técnica se haya ejecutado.", "a": true}, {"id": "kumite-071", "m": "kumite", "en": "If the organizer has a check-up of equipment before line-up, it is still KANSA's responsibility to ensure that the equipment is in accordance with the rules.", "es": "Si el organizador realiza una revisión del equipo antes de la alineación, sigue siendo responsabilidad de KANSA asegurarse de que el equipo es conforme al reglamento.", "a": true}, {"id": "kumite-072", "m": "kumite", "en": "An Athlete who stays within the competition area can score on an Athlete outside the competition area.", "es": "Un atleta que permanezca dentro del área de competición puede puntuar a un atleta fuera del área de competición.", "a": true}, {"id": "kumite-073", "m": "kumite", "en": "ATO SHIBARAKU means \"15 seconds of bout time remaining\".", "es": "ATO SHIBARAKU significa \"quedan 15 segundos de combate\".", "a": true}, {"id": "kumite-074", "m": "kumite", "en": "ATO SHIBARAKU means \"10 seconds of bout time remaining\".", "es": "ATO SHIBARAKU significa \"quedan 10 segundos de combate\".", "a": false}, {"id": "kumite-075", "m": "kumite", "en": "A \"skin touch\" to the throat is allowed only in Senior competition.", "es": "Un \"skin touch\" en la garganta sólo está permitido en la competición Senior.", "a": false}, {"id": "kumite-076", "m": "kumite", "en": "If there are no points at the end of a bout in team matches the Referee will call for HANTEI.", "es": "Si no hay puntos al final de un combate por equipos, el árbitro pedirá HANTEI.", "a": false}, {"id": "kumite-077", "m": "kumite", "en": "If an Athlete has been asked before the bout starts, and confirms wearing a groin guard, and it later proves that this is not so, the Athlete will receive a warning or penalty for MUBOBI.", "es": "Si se le pregunta a un atleta antes de que comience el combate si lleva protector inguinal y este lo confirma, pero posteriormente se comprueba que no es así, el atleta recibirá una advertencia o una sanción por MUBOBI.", "a": false}, {"id": "kumite-078", "m": "kumite", "en": "An Athlete can be penalised for exaggeration even if there is an actual injury.", "es": "Un atleta puede ser penalizado por exageración incluso si exista una lesión real.", "a": true}, {"id": "kumite-079", "m": "kumite", "en": "The Referee declares the winner, \"AO (AKA) NO KACHI\", and if necessary, breaks the tie in case of HANTEI.", "es": "El árbitro declarará al ganador ‘’AO (AKA) NO KACHI\", y si es necesario, desempatará en caso de HANTEI.", "a": true}, {"id": "kumite-080", "m": "kumite", "en": "In the event of a tied score at the end of an inconclusive bout the the Referee and the four Judges will decide the bout by HANTEI.", "es": "En caso de empate al final de un combate no concluyente, el árbitro y los cuatro jueces decidirán el combate por HANTEI.", "a": true}, {"id": "kumite-081", "m": "kumite", "en": "If the Referee Panel has made a decision not in accordance with the Rules of Competition, KANSA will immediately blow his whistle.", "es": "Si el panel de arbitraje haya tomado una decisión que no esté de acuerdo con el Reglamento de Competición, KANSA hará sonar inmediatamente su silbato.", "a": true}, {"id": "kumite-082", "m": "kumite", "en": "An Athlete should not be penalized for being winded (loss of breath as a consequence of a technique) or simply reacting to an impact even if the technique merited a point by the opponent.", "es": "Un atleta no debe ser penalizado por estar sin aliento (pérdida de aliento como consecuencia de una técnica) o simplemente por reaccionar a un impacto, incluso si la técnica mereció un punto por parte del oponente.", "a": true}, {"id": "kumite-083", "m": "kumite", "en": "In team matches, there is no extra bout.", "es": "En los encuentros por equipos no hay combate extra.", "a": false}, {"id": "kumite-084", "m": "kumite", "en": "Only the first correctly executed technique of a combination will score.", "es": "Sólo puntuará la primera técnica correctamente ejecutada de una combinación.", "a": false}, {"id": "kumite-085", "m": "kumite", "en": "Athletes that appear at the competition area with unauthorized equipment or irregular Karate Gi, will be given one minute to correct the attire.", "es": "A los atletas que se presenten en el área de competición con equipamiento no autorizado o un Karate Gi irregular, se les dará un minuto para corregir el atuendo.", "a": false}, {"id": "kumite-086", "m": "kumite", "en": "Athletes that are winded as a result of an impact, should be allowed time to catch their breath before the bout is resumed.", "es": "A los atletas que estén sin aliento como resultado de un impacto se les debe dar tiempo para recuperar el aliento antes de reanudar el combate.", "a": true}, {"id": "kumite-087", "m": "kumite", "en": "JODAN is described as the shoulders and the area above the collarbones.", "es": "JODAN se describe como los hombros y la zona por encima de la clavícula.", "a": false}, {"id": "kumite-088", "m": "kumite", "en": "IPPON is awarded for JODAN kicks or any techniques against an opponent whose any part of the body other than the feet is in contact with the Tatami.", "es": "IPPON se concede por patadas JODAN o cualquier técnica contra un oponente cuya cualquier parte del cuerpo, que no sean los pies, esté en contacto con el tatami.", "a": false}, {"id": "kumite-089", "m": "kumite", "en": "HANSOKU CHUI will be given for feigning of injury.", "es": "Se concederá HANSOKU CHUI por fingir una lesión.", "a": false}, {"id": "kumite-090", "m": "kumite", "en": "HANSOKU will be given for the first instance of exaggerating an injury.", "es": "Se dará HANSOKU por el primer caso de exageración de una lesión.", "a": false}, {"id": "kumite-091", "m": "kumite", "en": "A loss of breath by the recipient of a CHUDAN technique indicates lack of control.", "es": "La pérdida de aliento por parte del receptor de una técnica CHUDAN indica falta de control.", "a": false}, {"id": "kumite-092", "m": "kumite", "en": "An Athlete can be given HANSOKU directly for exaggerating the effects of injury.", "es": "Se puede dar HANSOKU directamente a un atleta por exagerar los efectos de una lesión.", "a": true}, {"id": "kumite-093", "m": "kumite", "en": "A technique, even if effective, delivered after an order to suspend or halt the bout willl not score and can result in a penalty being imposed on the offender.", "es": "Una técnica, incluso si es efectiva, realizada después de una orden de suspender o parar el combate, no será puntuada y puede dar lugar a que se imponga una sanción al infractor.", "a": true}, {"id": "kumite-094", "m": "kumite", "en": "If there is an error in the draw and the wrong Athletes compete, this cannot be changed afterwards.", "es": "Si hay un error en el sorteo y compiten los atletas equivocados, esto no podrá cambiarse posteriormente.", "a": false}, {"id": "kumite-095", "m": "kumite", "en": "Correctly executed techniques landed at the moment the time runs out are valid.", "es": "Una técnica eficaz realizada al mismo tiempo que el final del combate es válida.", "a": true}, {"id": "kumite-096", "m": "kumite", "en": "If an Athlete is injured and it is considered to be their own fault (MUBOBI), the Referee will decline to give a warning or penalty to the opponent.", "es": "Si un atleta se lesiona y se considera que es por su propia culpa (MUBOBI), el árbitro declinará dar una advertencia o penalización al oponente.", "a": true}, {"id": "kumite-097", "m": "kumite", "en": "KANSA has no vote or authority in matters of judgments, such as whether a score was valid or not, unless there has been an error in the application of the rules.", "es": "KANSA no tiene voto ni autoridad en cuestiones de juicios tales como si una puntuación ha sido válida o no, a menos que haya habido un error en la aplicación de las reglas.", "a": true}, {"id": "kumite-098", "m": "kumite", "en": "YUKO is always awarded for punches on the back.", "es": "YUKO siempre se concede por técnicas de puño en la espalda.", "a": false}, {"id": "kumite-099", "m": "kumite", "en": "\"Skin touch\" is allowed in all official categories.", "es": "\"Skin touch\" está permitido en todas las categorías oficiales.", "a": true}, {"id": "kumite-100", "m": "kumite", "en": "An Athlete who does not obey the Referee's orders will be given SHIKKAKU.", "es": "Un atleta que no obedezca las órdenes del árbitro recibirá SHIKKAKU.", "a": true}, {"id": "kumite-101", "m": "kumite", "en": "The Score Supervisor will order the Referee to halt the bout if there is a contravention of the rules.", "es": "El supervisor de puntuación ordenará al árbitro detener el combate si hay una contravención del reglas.", "a": false}, {"id": "kumite-102", "m": "kumite", "en": "If in a combination, the first technique merits a YUKO and the second merits a penalty, both shall be given.", "es": "Si en una combinación la primera técnica merece un YUKO y la segunda merece una penalización, se darán ambas.", "a": false}, {"id": "kumite-103", "m": "kumite", "en": "\"Skin touch\" is defined as touching the target without transferring energy into the protective helmet or head of the Athlete.", "es": "\"Skin touch\" se define como un contacto con el objetivo sin transferir energía a el casco o la cabeza del atleta.", "a": true}, {"id": "kumite-104", "m": "kumite", "en": "It is not possible to score while lying on the floor.", "es": "No es posible marcar estando tumbado en el suelo.", "a": false}, {"id": "kumite-105", "m": "kumite", "en": "An Athlete not wearing the WKF approved equipment will be given two minutes to change for the approved type.", "es": "Un atleta que no lleve el equipo aprobado por la WKF dispondrá de dos minutos para cambiarlo por el tipo aprobado.", "a": true}, {"id": "kumite-106", "m": "kumite", "en": "An Athlete injured in Kumite and withdrawn under the ten-second rule cannot compete in the Kata competition.", "es": "Un atleta lesionado en Kumite y retirado bajo la regla de los diez segundos no podrá competir en la competición de Kata.", "a": false}, {"id": "kumite-107", "m": "kumite", "en": "An injured Athlete who has been declared unfit to fight by the Tournament Doctor cannot fight again in that competition.", "es": "Un atleta lesionado que haya sido declarado no apto para combatir por el médico del torneo no podrá volver a combatir en esa competición.", "a": true}, {"id": "kumite-108", "m": "kumite", "en": "If an Athlete behaves badly on the competition area after the end of the bout or match, the Referee can still give SHIKKAKU.", "es": "Si un atleta se comporta mal en el área de competición después del final del encuentro o combate, el árbitro aún puede dar SHIKKAKU.", "a": true}, {"id": "kumite-109", "m": "kumite", "en": "KANSA has a vote in cases of SHIKKAKU.", "es": "KANSA tiene voto en los casos de SHIKKAKU.", "a": false}, {"id": "kumite-110", "m": "kumite", "en": "In Male team matches if a team wins three bouts, then the match is over at that point.", "es": "En combates por equipos masculinos, si un equipo gana tres combates, entonces el combate finaliza en ese momento.", "a": false}, {"id": "kumite-111", "m": "kumite", "en": "In Female team matches if a team wins two bouts, then the match is over at that point.", "es": "En los combates por equipos femeninos, si un equipo gana dos combates, el combate finalizará en ese momento.", "a": false}, {"id": "kumite-112", "m": "kumite", "en": "If an Athlete seizes the opponent and does not perform an immediate technique or throw the Referee will call \"YAME\".", "es": "Si un atleta agarra al oponente y no realiza una técnica o derribo inmediato, el árbitro anunciara \"YAME\".", "a": true}, {"id": "kumite-113", "m": "kumite", "en": "An Athlete who commits an act which harms the prestige and honour of Karate-Do will be given HANSOKU.", "es": "Un atleta que cometa un acto que dañe el prestigio y el honor del Karate-Do será sancionado con HANSOKU.", "a": false}, {"id": "kumite-114", "m": "kumite", "en": "If an action of an Athlete is considered to be dangerous and deliberately violates the rules concerning prohibited behaviour, the Athlete will be given SHIKKAKU.", "es": "Si una acción de un atleta se considere peligrosa e infrinja deliberadamente las reglas relativas al comportamiento prohibido, se dará al atleta SHIKKAKU.", "a": true}, {"id": "kumite-115", "m": "kumite", "en": "Correctly executed techniques after the time-up signal are valid.", "es": "Las técnicas correctamente ejecutadas después de la señal de tiempo son válidas.", "a": false}, {"id": "kumite-116", "m": "kumite", "en": "Correctly executed techniques upon or after \"WAKARETE\" are valid.", "es": "Las técnicas ejecutadas correctamente durante o después de \"WAKARETE\" son válidas.", "a": false}, {"id": "kumite-117", "m": "kumite", "en": "At HANTEI, if three Judges signal victory for AKA and the fourth Judge signals victory for AO, the Referee must give victory for AKA.", "es": "En HANTEI, si tres jueces señalan la victoria para AKA y el cuarto juez señala la victoria para AO, el árbitro debe dar la victoria a AKA.", "a": true}, {"id": "kumite-118", "m": "kumite", "en": "Passivity cannot be given to an Athlete having a lead by points or SENSHU.", "es": "No se puede dar pasividad a un atleta que tenga ventaja por punto o SENSHU.", "a": true}, {"id": "kumite-119", "m": "kumite", "en": "Only the Coach designated for the specific bout is allowed to guide the Athlete from the place allocated to the Coach close to the competition area.", "es": "Sólo el entrenador designado para el combate específico puede guiar al atleta desde el lugar asignado al entrenador cerca del área de competición.", "a": true}, {"id": "kumite-120", "m": "kumite", "en": "If an Athlete does not regain his or her feet within ten seconds, the Referee will announce \"KIKEN\" and \"KACHI\" to the opponent.", "es": "Si un atleta no se recupera en diez segundos, el árbitro anunciará \"KIKEN\" y \"KACHI\" al oponente.", "a": false}, {"id": "kumite-121", "m": "kumite", "en": "If an Athlete is thrown and lands partly outside the competition area, the Referee will immediately call \"YAME\".", "es": "Si un atleta es derribado y cae parcialmente fuera del área de competición, el árbitro anunciará inmediatamente \"YAME\".", "a": false}, {"id": "kumite-122", "m": "kumite", "en": "The Athlete is not allowed to signal to the Coach to request a video review.", "es": "El atleta no podrá señalar al entrenador el deseo de que solicite una revisión de vídeo.", "a": false}, {"id": "kumite-123", "m": "kumite", "en": "The Athlete should be examined outside the Tatami.", "es": "El atleta debe ser examinado fuera del tatami.", "a": true}, {"id": "kumite-124", "m": "kumite", "en": "KANSA has to blow the whistle if the Judges are holding the joysticks in the wrong hands.", "es": "KANSA tiene que hacer sonar el silbato si los jueces están sujetando los joysticks en las manos equivocadas.", "a": true}, {"id": "kumite-125", "m": "kumite", "en": "Gum-shields are obligatory for all Kumite Athletes.", "es": "Los protectores bucales son obligatorios para todos los atletas de Kumite.", "a": true}, {"id": "kumite-126", "m": "kumite", "en": "After a throw the Referee will allow a maximum of two seconds for a score to be made.", "es": "Después de un derribo, el árbitro permitirá un máximo de dos segundos para que se realice una puntuación.", "a": false}, {"id": "kumite-127", "m": "kumite", "en": "If an Athlete scores with a strong kick and propels the opponent out of the area, the Referee should award WAZA-ARI and give the opponent a warning or penalty for JOGAI.", "es": "Si un atleta puntúa con una fuerte patada e impulsa al oponente fuera del área, el árbitro deberá conceder WAZA-ARI y dar al oponente una advertencia o penalización por JOGAI.", "a": false}, {"id": "kumite-128", "m": "kumite", "en": "If an official protest is lodged the ensuing bouts must be delayed until the result of the protest is given.", "es": "Si se presenta una protesta oficial, los encuentros siguientes deben retrasarse hasta que se dé el resultado de la protesta.", "a": false}, {"id": "kumite-129", "m": "kumite", "en": "If the Referee awards a point for a technique which has caused injury KANSA should signal for the bout to be stopped.", "es": "Si el árbitro conceda un punto por una técnica que haya causado lesión, KANSA deberá indicar que se detenga el encuentro.", "a": false}, {"id": "kumite-130", "m": "kumite", "en": "If the Referee fails to hear the time-up bell, the Scorekeeper should whistle.", "es": "Si el árbitro no oye la señal de final de tiempo, el anotador de puntuación hará sonar su silbato.", "a": false}, {"id": "kumite-131", "m": "kumite", "en": "WAKARETE for breaking up a clinch can be given at any time of the bout.", "es": "Para romper un clinch en cualquier momento del combate se puede dar WAKARETE.", "a": true}, {"id": "kumite-132", "m": "kumite", "en": "FUKUSHIN SHUGO is obligatory before imposing SHIKKAKU.", "es": "FUKUSHIN SHUGO es obligatorio para poder dar SHIKKAKU.", "a": true}, {"id": "kumite-133", "m": "kumite", "en": "If an Athlete is injured during a bout and needs medical treatment three minutes will be given in which to receive it, after that the Referee will decide whether the Athlete should be declared unfit to fight or whether more time should be given.", "es": "Si un atleta resulta lesionado durante un combate y necesite tratamiento médico, se le concederán tres minutos para recibirlo, tras los cuales el árbitro decidirá si el atleta será declarado no apto para combatir o si se le concederá más tiempo.", "a": true}, {"id": "kumite-134", "m": "kumite", "en": "An Athlete who exits the competition area (JOGAI) with less than 15 seconds of bout time remaining will be given a minimum of CHUI.", "es": "A un atleta que salga del área (JOGAI) con menos de 15 segundos de combate restantes, se le dará un mínimo de CHUI.", "a": false}, {"id": "kumite-135", "m": "kumite", "en": "To correct a score given to the wrong Athlete, the Referee should turn towards the Athlete given the score in error, make the sign of TORIMASEN, and then give the score to the opponent.", "es": "Para corregir una puntuación dada al atleta equivocado, el árbitro debe girarse hacia el atleta al que se le ha dado la puntuación por error, hacer el signo de TORIMASEN, y después dar la puntuación al oponente.", "a": true}, {"id": "kumite-136", "m": "kumite", "en": "If an Athlete scores with a wellcontrolled CHUDAN kick, then accidentally punches his opponent in the face causing a slight injury, WAZAARI and a warning should be given.", "es": "Si un atleta puntúa con una patada CHUDAN bien controlada y, después, accidentalmente golpea a su oponente en la cara causándole una herida leve, se debe dar WAZA-ARI y una advertencia.", "a": false}, {"id": "kumite-137", "m": "kumite", "en": "If an injured Athlete has been given medical treatment and the Official Doctor says that the Athlete can continue fighting the Referee cannot overrule the Doctor's decision.", "es": "Si un atleta lesionado ha recibido tratamiento médico y el médico oficial dice que el atleta puede continuar combatiendo, el árbitro no puede invalidar la decisión del médico.", "a": false}, {"id": "kumite-138", "m": "kumite", "en": "The Referee can stop the bout even if the Judges do not signal.", "es": "El árbitro puede detener el combate incluso si los jueces no lo señalan.", "a": true}, {"id": "kumite-139", "m": "kumite", "en": "Once WAKARETE is called by the Referee the Coaches do not have the opportunity to make a video review request unless the techniques happened before WAKARETE was called.", "es": "Una vez que el árbitro anuncia WAKARETE, los entrenadores no tienen la oportunidad de solicitar una revisión de vídeo, a menos que las técnicas se hayan producido antes de que se anuncie WAKARETE.", "a": true}, {"id": "kumite-140", "m": "kumite", "en": "\"Avoiding Combat\" refers to a situation where an Athlete attempts to prevent the opponent from having the opportunity to score by using timewasting behaviour.", "es": "\"Evitar el combate\" se refiere a una situación en la que un atleta intenta evitar que el oponente tenga la oportunidad de puntuar utilizando un comportamiento de pérdida de tiempo.", "a": true}, {"id": "kumite-141", "m": "kumite", "en": "TSUZUKETE, unless preceded by WAKARETE, is not used if there is less than 15 seconds left of the bout.", "es": "TSUZUKETE, a menos que vaya precedido de WAKARETE, no se utiliza si quedan menos de 15 segundos de combate.", "a": true}, {"id": "kumite-142", "m": "kumite", "en": "In team matches if two Athletes injure each other and are unable to continue, and the score is equal, the Referee will announce HIKIWAKE.", "es": "En encuentros por equipos, si dos atletas se lesionan mutuamente y no pueden continuar y la puntuación es igual, el árbitro anunciará HIKIWAKE.", "a": false}, {"id": "kumite-143", "m": "kumite", "en": "if there are less than 15 seconds of bout time remaining and a losing Athlete, desperately trying to equalise, exits the area (JOGAI) the Athlete will be given a minimum of HANSOKU CHUI.", "es": "Si quedan menos de 15 segundos de combate y el atleta que va perdiendo, intentando desesperadamente igualar, se sale del área (JOGAI), se le dará un mínimo de HANSOKU CHUI.", "a": true}, {"id": "kumite-144", "m": "kumite", "en": "Techniques which land below the belt cannot score.", "es": "Las técnicas realizadas por debajo del cinturón no pueden puntuar.", "a": false}, {"id": "kumite-145", "m": "kumite", "en": "Techniques, which land on the shoulder blade, can score.", "es": "Las técnicas que se realicen sobre el omóplato pueden puntuar.", "a": true}, {"id": "kumite-146", "m": "kumite", "en": "If AKA accidentally kicks AO on the hip and AO cannot continue the bout, then AO will be given KIKEN.", "es": "Si AKA accidentalmente golpea a AO en la cadera y AO no puede continuar el combate, entonces AO recibirá KIKEN.", "a": false}, {"id": "kumite-147", "m": "kumite", "en": "If an Athlete is obviously out of breath due to lack of endurance, the Referee should stop the bout to give the Athlete time to recover.", "es": "Si un atleta está obviamente sin aliento debido a la falta de resistencia, el árbitro deberá detener el combate para darle tiempo a recuperarse.", "a": false}, {"id": "kumite-148", "m": "kumite", "en": "An Athlete who establishes a clear lead of eight points is declared the winner.", "es": "El atleta que establezca una clara ventaja de ocho puntos será declarado vencedor.", "a": true}, {"id": "kumite-149", "m": "kumite", "en": "When time is up, the Athlete who has scored the most points is declared the winner.", "es": "Cuando se acabe el tiempo, el atleta que haya obtenido más puntos será declarado ganador.", "a": true}, {"id": "kumite-150", "m": "kumite", "en": "An otherwise correctly executed technique will be penalized if executed at the same time as WAKARETE has been called.", "es": "Una técnica correctamente ejecutada será penalizada si se ejecuta al mismo tiempo que se ha ordenado WAKARETE.", "a": false}, {"id": "kumite-151", "m": "kumite", "en": "There are two degrees of official warnings.", "es": "Hay dos grados de advertencias oficiales.", "a": true}, {"id": "kumite-152", "m": "kumite", "en": "CHUI is given, up to three times, for smaller infractions.", "es": "CHUI se da, hasta tres veces, por infracciones menores.", "a": true}, {"id": "kumite-153", "m": "kumite", "en": "HANSOKU CHUI cannot be given if three CHUI have not already been given.", "es": "No se puede dar HANSOKU CHUI si no se han dado ya tres CHUI.", "a": false}, {"id": "kumite-154", "m": "kumite", "en": "A warning or penalty for MUBOBI is only given if an Athlete is hit or injured through their own fault or negligence.", "es": "Una advertencia o penalización por MUBOBI sólo se da cuando un atleta es golpeado o lesionado por su propia culpa o negligencia.", "a": true}, {"id": "kumite-155", "m": "kumite", "en": "An Athlete who is hit through their own fault and exaggerates the effect should receive a warning or penalty for MUBOBI or exaggeration but not both.", "es": "Un atleta que es golpeado por su propia culpa y exagera el efecto debe recibir una advertencia o penalización por MUBOBI o exageración, pero no ambas.", "a": false}, {"id": "kumite-156", "m": "kumite", "en": "If an Athlete makes a good CHUDAN kick and the opponent catches the leg a score cannot be given.", "es": "Si un atleta realiza una buena patada CHUDAN y el oponente atrapa la pierna, no se puede dar puntuación.", "a": false}, {"id": "kumite-157", "m": "kumite", "en": "An Athlete makes a JODAN kick with all six scoring criteria. The opponent puts the hand up to intercept the kick and the hand then lightly hits his own face, the Referee can give IPPON since the kick was not effectively blocked.", "es": "Un atleta realiza una patada JODAN con los seis criterios de puntuación. El oponente levanta la mano para interceptar la patada y entonces la mano golpea ligeramente su propia cara. El árbitro puede dar IPPON, ya que la patada no fue bloqueada eficazmente.", "a": false}, {"id": "kumite-158", "m": "kumite", "en": "A male team can compete with only two Athletes.", "es": "Un equipo masculino puede competir con sólo dos atletas.", "a": false}, {"id": "kumite-159", "m": "kumite", "en": "Authorised advertising for WKF is displayed on the left sleeve of the Karate Gi.", "es": "La publicidad autorizada de WKF se muestra en la manga izquierda del Karate Gi.", "a": true}, {"id": "kumite-160", "m": "kumite", "en": "National Federations are not allowed to put advertising on the Athlete's Karate Gi.", "es": "Las Federaciones Nacionales no están autorizadas a poner publicidad en el Karate Gi del atleta.", "a": false}, {"id": "kumite-161", "m": "kumite", "en": "A Kumite Athlete who receives KIKEN cannot compete again in that tournament.", "es": "Un atleta de Kumite que reciba KIKEN no podrá volver a competir en ese torneo.", "a": false}, {"id": "kumite-162", "m": "kumite", "en": "An extra bout is used only for team matches.", "es": "Un combate extra se utiliza sólo para encuentros por equipos.", "a": false}, {"id": "kumite-163", "m": "kumite", "en": "KANSA needs to blow the whistle if the Referee gives a score to an Athlete and MUBOBI to the other.", "es": "KANSA tiene que hacer sonar el silbato si el árbitro da una puntuación a un atleta y MUBOBI al otro.", "a": true}, {"id": "kumite-164", "m": "kumite", "en": "Serious violation of conduct, discipline, or malicious behavior merits HANSOKU CHUI.", "es": "Una violación grave de la conducta o disciplina o comportamiento malicioso merece HANSOKU CHUI.", "a": false}, {"id": "kumite-165", "m": "kumite", "en": "In international competitions, the Referee must not have the same nationality as either of the Athletes, although one of the Judges can if both Coaches agree.", "es": "En competiciones internacionales, el árbitro no debe tener la misma nacionalidad que ninguno de los atletas, aunque uno de los jueces puede si ambos entrenadores están de acuerdo.", "a": false}, {"id": "kumite-166", "m": "kumite", "en": "KANSA will line up together with the Referee and the Judges.", "es": "KANSA se alineará junto con el árbitro y los jueces.", "a": false}, {"id": "kumite-167", "m": "kumite", "en": "The Coaches will be seated outside the safety area, on their respective sides facing towards the official table.", "es": "Los entrenadores se sentarán fuera de la zona de seguridad, en sus respectivos lados, mirando hacia la mesa oficial.", "a": false}, {"id": "kumite-168", "m": "kumite", "en": "KANSA does not need to interfere if the Referee gives a score to an Athlete and exaggeration to the other.", "es": "KANSA no necesita interferir si el árbitro da una puntuación a un atleta y una exageración al otro.", "a": false}, {"id": "kumite-169", "m": "kumite", "en": "In team matches the Referee and the Judges will rotate for each bout - provided that all hold the required license.", "es": "En los encuentros por equipos, el árbitro y los jueces rotarán para cada combate, siempre que todos posean la licencia requerida.", "a": true}, {"id": "kumite-170", "m": "kumite", "en": "The Referee can move around the entire Tatami including the safety zones.", "es": "El árbitro puede moverse por todo el tatami, incluidas las zonas de seguridad.", "a": true}, {"id": "kumite-171", "m": "kumite", "en": "The red and blue belts must be without any personal embroideries or markings.", "es": "Los cinturones rojos y azules deben estar sin bordados o marcas personales.", "a": true}, {"id": "kumite-172", "m": "kumite", "en": "Personal embroidery on the Karate Gi is allowed only in bouts for medals.", "es": "Los bordados personales en el Karate Gi sólo están permitidos en los combates por medallas.", "a": false}, {"id": "kumite-173", "m": "kumite", "en": "If contact is considered by the Referee to be strong, but does not diminish the Athlete's chances of winning, a warning (CHUI) can be given.", "es": "Si el árbitro considera que un contacto es fuerte, pero no disminuye las posibilidades del atleta de ganar, se puede dar una advertencia (CHUI).", "a": true}, {"id": "kumite-174", "m": "kumite", "en": "An obvious overreaction to a contact will receive a CHUI.", "es": "Una reacción exagerada a un contacto recibirá un CHUI.", "a": false}, {"id": "kumite-175", "m": "kumite", "en": "Judges cannot indicate a score before the Referee stops the bout.", "es": "Los jueces no pueden indicar una puntuación antes de que el árbitro detenga el combate.", "a": false}, {"id": "kumite-176", "m": "kumite", "en": "An obvious display of exaggeration will receive HANSOKU.", "es": "Una muestra obvia de exageración recibirá HANSOKU.", "a": false}, {"id": "kumite-177", "m": "kumite", "en": "Any instance of feigning an injury, however slight, will receive a minimum warning of CHUI.", "es": "Cualquier caso de fingir una lesión, por leve que sea, recibirá una advertencia mínima de CHUI.", "a": true}, {"id": "kumite-178", "m": "kumite", "en": "An obvious display of any feigning such as staggering around, falling on the floor, standing up and falling down again, and so on, will receive SHIKKAKU directly.", "es": "Una muestra obvia de cualquier fingimiento, como tambalearse, caerse al suelo, levantarse y volver a caerse, etc., recibirá directamente SHIKKAKU.", "a": true}, {"id": "kumite-179", "m": "kumite", "en": "Any feigning of an injury from a technique that in fact has been determined by the Judges as a point will as a minimum result in HANSOKU CHUI.", "es": "Cualquier fingimiento de lesión de una técnica que haya sido determinada por los jueces como un punto, resultará como mínimo en HANSOKU CHUI.", "a": true}, {"id": "kumite-180", "m": "kumite", "en": "If an Athlete scores with more than one consecutive technique before YAME, the Judges must show the higher score regardless of which sequence the techniques scored.", "es": "Si un atleta puntúa con más de una técnica consecutiva antes de YAME, los jueces deben mostrar el punto más alto, independientemente de la secuencia en que las técnicas hayan puntuado.", "a": true}, {"id": "kumite-181", "m": "kumite", "en": "In team matches, if after the extra bout there are no scores, or it is equal scores with no SENSHU, the bout will be decided by HANTEI.", "es": "En encuentros por equipos, si después del combate extra no hay puntuación o hay igualdad de puntuación sin SENSHU, el encuentro se decidirá por HANTEI.", "a": false}, {"id": "kumite-182", "m": "kumite", "en": "JOGAI occurs when an Athlete exits from the competition area, and it is not caused by the opponent.", "es": "JOGAI se produce cuando un atleta sale del área de competición y no es causado por el adversario.", "a": true}, {"id": "kumite-183", "m": "kumite", "en": "The minimum warning for running away, avoiding combat and/or timewasting during ATO SHIBARAKU is HANSOKU CHUI.", "es": "La advertencia mínima por huir, evitar combate y/o perder tiempo durante ATO SHIBARAKU, es HANSOKU CHUI.", "a": true}, {"id": "kumite-184", "m": "kumite", "en": "The pivotal point of the throw must not be above the thrower's hip level and the opponent must be held onto throughout, so that a safe landing can be made.", "es": "El punto de giro del lanzamiento no debe estar por encima del nivel de la cadera del lanzador y el adversario debe ser sujetado en todo momento, de forma que se pueda realizar un aterrizaje seguro.", "a": true}, {"id": "kumite-185", "m": "kumite", "en": "Holding the opponent's Karate Gi is not permitted to break a fall.", "es": "No está permitido agarrarse al Karate Gi del adversario para frenar una caída.", "a": false}, {"id": "kumite-186", "m": "kumite", "en": "KANSA does not need to interfere if the Referee gives a score for a technique done after the time is up.", "es": "KANSA no necesita interferir si el árbitro da una puntuación por una técnica realizada una vez finalizado el tiempo.", "a": false}, {"id": "kumite-187", "m": "kumite", "en": "YUKO is worth one point.", "es": "YUKO vale un punto.", "a": true}, {"id": "kumite-188", "m": "kumite", "en": "WAZA-ARI is worth two points.", "es": "WAZA-ARI vale dos puntos.", "a": true}, {"id": "kumite-189", "m": "kumite", "en": "IPPON is worth three points.", "es": "IPPON vale tres puntos.", "a": true}, {"id": "kumite-190", "m": "kumite", "en": "It is the duty of the Tatami Manager to ensure before each bout or match that the Athletes are wearing the approved equipment.", "es": "Es obligación del tatami manager asegurarse antes de cada combate o encuentro de que los atletas llevan el equipamiento homologado.", "a": false}, {"id": "kumite-191", "m": "kumite", "en": "WAZA-ARI is awarded for CHUDAN kicks.", "es": "Se concederá WAZA-ARI por las patadas CHUDAN.", "a": true}, {"id": "kumite-192", "m": "kumite", "en": "IPPON is awarded for JODAN kicks and any technique which is delivered on an opponent who has been thrown, has fallen on their own accord, or is otherwise off their feet.", "es": "IPPON se concede por JODAN patadas y qualquier técnica realizada sobre un oponente que ha sido derribado, ha caído por su propia falta, o se ha caido de cualquier forma.", "a": false}, {"id": "kumite-193", "m": "kumite", "en": "Individual bouts cannot be declared a tie.", "es": "Los combates individuales no pueden ser declarados empate.", "a": false}, {"id": "kumite-194", "m": "kumite", "en": "Passivity can be given to any Athlete at any time.", "es": "Se puede dar pasividad a cualquier atleta en cualquier momento.", "a": false}, {"id": "kumite-195", "m": "kumite", "en": "Passivity cannot be given during the first 15 seconds of a bout.", "es": "No se puede dar pasividad durante los primeros 15 segundos de un combate.", "a": true}, {"id": "kumite-196", "m": "kumite", "en": "Simulated attacks with the head, knees, or elbows are offenses.", "es": "Los ataques simulados con la cabeza, las rodillas o los codos son infracciones.", "a": true}, {"id": "kumite-197", "m": "kumite", "en": "Avoiding combat during the last 15 seconds of the bout (ATO SHIBARAKU) will as a minimum result in HANSOKU CHUI and loss of SENSHU.", "es": "Evitar el combate durante los últimos 15 segundos del combate (ATO SHIBARAKU) resultará como mínimo en HANSOKU CHUI y pérdida de SENSHU.", "a": true}, {"id": "kumite-198", "m": "kumite", "en": "The Head Coach of a delegation can protest about a judgment to the members of the Referee Panel.", "es": "El entrenador jefe de una delegación puede protestar sobre un juicio ante los miembros del panel de arbitraje.", "a": false}, {"id": "kumite-199", "m": "kumite", "en": "Jacket ties must be tied.", "es": "Los lazos de las chaquetas deben estar atados.", "a": true}, {"id": "kumite-200", "m": "kumite", "en": "At the beginning of a bout jackets without ties can be used.", "es": "Al comienzo de un combate se pueden utilizar chaquetas sin lazos.", "a": false}, {"id": "kumite-201", "m": "kumite", "en": "In individual competition, an Athlete can be replaced by another after the draw has taken place.", "es": "En una competición individual, un atleta puede ser sustituido por otro después de haberse realizado el sorteo.", "a": false}, {"id": "kumite-202", "m": "kumite", "en": "At medal bouts, male Coaches are required to wear a dark suit, shirt, tie and shoes covering the toes.", "es": "En los combates por medallas los entrenadores masculinos deben llevar traje oscuro, camisa y corbata, además de zapatos que cubran todo el pie.", "a": true}, {"id": "kumite-203", "m": "kumite", "en": "At medal bouts, female Coaches can choose to wear a dress, pantsuit or a combination of jacket and skirt in dark colours and shoes covering the toes.", "es": "En los combates por medallas, las entrenadoras podrán elegir entre llevar vestido, traje pantalón o una combinación de chaqueta y falda en colores oscuros, además de zapatos que cubran todo el pie.", "a": true}, {"id": "kumite-204", "m": "kumite", "en": "At medal bouts, female Coaches cannot wear religious headwear.", "es": "En los combates por medallas, las entrenadoras no pueden llevar tocados religiosos.", "a": false}, {"id": "kumite-205", "m": "kumite", "en": "An Athlete that refuses to follow the instructions of the Referee or displays a loss of temper will automatically receive HANSOKU.", "es": "Un atleta que se niegue a seguir las instrucciones del árbitro o muestre una pérdida de temperamento recibirá automáticamente HANSOKU.", "a": false}, {"id": "kumite-206", "m": "kumite", "en": "Athletes are not entitled to a period of time between bouts, equal to the standard duration time of the bout, for purpose of rest.", "es": "Los atletas no tienen derecho a un período de tiempo entre combates igual al tiempo de duración estándar del combate, con el propósito de descansar.", "a": false}, {"id": "kumite-207", "m": "kumite", "en": "Passivity cannot be given after less than 15 seconds of bout time remaining.", "es": "La pasividad no puede darse cuando quedan menos de 15 segundos del combate.", "a": true}, {"id": "kumite-208", "m": "kumite", "en": "Any excessive celebration, such as falling on one's knees etc., political, or religious expressions, during or immediately after the bout or match, are prohibited and can be subject to a fine equal to the protest fee determined by the Executive Committee.", "es": "Cualquier celebración excesiva, como arrodillarse, etc., expresiones políticas o religiosas, durante o inmediatamente después del combate, están prohibidas y pueden estar sujetas a una multa igual a la tasa de protesta determinada por la Comisión Ejecutiva.", "a": true}, {"id": "kumite-209", "m": "kumite", "en": "If an Athlete receives KIKEN, or SHIKKAKU, in Round-robin competition all previous bouts are voided from the result.", "es": "Si un atleta recibe KIKEN, o SHIKKAKU, en competición round-robin, todos los combates anteriores serán anulados del resultado.", "a": false}, {"id": "kumite-210", "m": "kumite", "en": "Grabbing the opponent's arm or Karate Gi with one hand is only allowed for attempting an immediate scoring technique or takedown.", "es": "Agarrar el brazo o Karate Gi del oponente con una mano, sólo está permitido para intentar una técnica inmediatamente puntuable o un derribo.", "a": false}, {"id": "kumite-211", "m": "kumite", "en": "Grabbing the opponent with both hands is never allowed during the bout.", "es": "Agarrar al oponente con ambas manos nunca está permitido durante el combate.", "a": false}, {"id": "kumite-212", "m": "kumite", "en": "It is the Tatami Manager's duty to appoint the video review Judge.", "es": "Es deber del tatami manager designar al juez de la revisión de vídeo.", "a": true}, {"id": "kumite-213", "m": "kumite", "en": "If the number of IPPON and WAZA ARI is equal, the decision will be made by HANTEI.", "es": "Si el número de IPPON y WAZA ARI es igual, la decisión será por HANTEI.", "a": false}, {"id": "kumite-214", "m": "kumite", "en": "In any individual bout, with equal score, and no SENSHU by either Athlete, the first criterion of the decision will be made based on the higher number of IPPON scored in the bout.", "es": "En cualquier combate individual, con igual puntuación y sin SENSHU por parte de ninguno de los atletas, el primer criterio de la decisión se tomará en base al mayor número de IPPON marcados en el combate.", "a": true}, {"id": "kumite-215", "m": "kumite", "en": "If one Athlete has a score indicated by more than one Judge and the score is different between the Judges, the higher will be applied, unless there is majority for a lower score.", "es": "Si un atleta tiene una puntuación indicada por más de un juez y la puntuación es diferente entre los jueces, se aplicará la más alta, a menos que haya una mayoría a favor de una puntuación más baja.", "a": true}, {"id": "kumite-216", "m": "kumite", "en": "The Tatami Manager must notify the central table if an Athlete has been stopped from further competition based on the 10-second rule.", "es": "El tatami manager debe notificar a la mesa central si un atleta no puede seguir compitiendo, basándose en la regla de los 10 segundos.", "a": true}, {"id": "kumite-217", "m": "kumite", "en": "The Timekeeper is responsible for starting the 3-minute count for an Athlete who is injured during a bout in progress and requires medical treatment.", "es": "El anotador de puntuación es responsable de iniciar el recuento de 3 minutos para un atleta que se lesione durante un combate en curso y requiera tratamiento médico.", "a": false}, {"id": "kumite-218", "m": "kumite", "en": "The Referee will not call YAME if an Athlete seizes the opponent and does not perform an immediate technique or throw.", "es": "El árbitro no anunciará YAME si un atleta agarra al oponente y no realiza una técnica o un lanzamiento inmediato.", "a": false}, {"id": "kumite-219", "m": "kumite", "en": "The Referee indicates the winner by hand signal and the order (AKA/AO NO KACHI), and by this action also resolves any tie.", "es": "El árbitro indicará el ganador mediante una señal con la mano y la orden (AKA/AO NO KACHI), y mediante esta acción también resolverá cualquier empate.", "a": true}, {"id": "kumite-220", "m": "kumite", "en": "If an Athlete seizes the opponent, the Referee will give several seconds for the Athlete to perform a throw or technique.", "es": "si un atleta agarra al oponente, el árbitro dará varios segundos para que el atleta realice un derribo o técnica.", "a": false}, {"id": "kumite-221", "m": "kumite", "en": "The Coach or NF representative will request the official protest form from the Tatami Manager.", "es": "El entrenador o representante de la FN solicitará la protesta oficial al tatami manager.", "a": true}, {"id": "kumite-222", "m": "kumite", "en": "The Referee can stop the bout and give a point without the Judges' opinion.", "es": "El árbitro puede parar el combate y dar un punto sin la opinión de los jueces.", "a": false}, {"id": "kumite-223", "m": "kumite", "en": "If the Referee does not call the Doctor in a 10-second rule situation, KANSA must blow the whistle.", "es": "Si el árbitro no llama al médico en una situación de regla de 10 segundos, KANSA debe hacer sonar el silbato.", "a": true}, {"id": "kumite-224", "m": "kumite", "en": "The winning team is the one with the most bout victories excluding those won by SENSHU.", "es": "El equipo ganador es el que tenga más combates ganados excluyendo los ganados por SENSHU.", "a": false}, {"id": "kumite-225", "m": "kumite", "en": "The red and blue belts must be no longer than three-quarters thigh length.", "es": "Los cinturones rojo y azul no deben ser más largos que tres cuartos de la longitud del muslo.", "a": true}, {"id": "kumite-226", "m": "kumite", "en": "The correct penalty for feigning an injury if the Judges have determined that the technique in fact was a score, is HANSOKU.", "es": "La penalización correcta por fingir una lesión si los jueces han determinado que la técnica de hecho era una puntuación, es HANSOKU.", "a": false}, {"id": "kumite-227", "m": "kumite", "en": "The information of officials implicated in the protest is completed by the Tatami Manager.", "es": "La información de los oficiales implicados en la protesta es completada por el tatami manager.", "a": true}, {"id": "kumite-228", "m": "kumite", "en": "Disqualification by KIKEN means that the Athlete is disqualified from that category, although it does not affect participation in another category.", "es": "La descalificación por KIKEN significa que los atletas son descalificados de esa categoría, aunque no afecta a la participación en otra categoría.", "a": true}, {"id": "kumite-229", "m": "kumite", "en": "Athletes are entitled to a rest period of time between bouts, equal to the standard duration time of the bout. The exception is in the case of change of equipment color, where this time is extended to five minutes.", "es": "Los atletas tienen derecho a un período de descanso entre combates igual al tiempo de duración estándar del combate. La excepción es en el caso de cambio de color de la equipacion donde este tiempo se amplía a cinco minutos.", "a": true}, {"id": "kumite-230", "m": "kumite", "en": "In any bout, if after full time the scores are equal, but one Athlete has obtained SENSHU, that Athlete will be declared the winner.", "es": "En cualquier combate, si después del tiempo completo las puntuaciones están igualadas, pero uno de los atletas ha obtenido SENSHU, ese atleta será declarado vencedor.", "a": true}, {"id": "kumite-231", "m": "kumite", "en": "By SENSHU is understood that one Athlete has achieved the first instance of scoring on the opponent without having the opponent also score before the signal.", "es": "Con SENSHU se entiende que un atleta ha conseguido la primera instancia de puntuación sobre el oponente sin que el oponente también haya puntuado antes de la señal.", "a": true}, {"id": "kumite-232", "m": "kumite", "en": "In the event that an Athlete falls, is thrown, or knocked down and does not regain his or her feet immediately, the Referee will call the Doctor, and at the same time start a count to ten indicating his count showing a finger for each second.", "es": "En el caso de que un atleta caiga o sea derribado y no se recupere inmediatamente, el árbitro llamará al médico y al mismo tiempo iniciará una cuenta hasta diez indicando su cuenta mostrando un dedo por cada segundo.", "a": false}, {"id": "kumite-233", "m": "kumite", "en": "An audible signal will be given by the Timekeeper 15 seconds before the actual end of the bout and the Referee will announce \"ATO SHIBARAKU\".", "es": "El cronometrador dará una señal acústica 15 segundos antes del final real del combate y el árbitro anunciará \"ATO SHIBARAKU\".", "a": true}, {"id": "kumite-234", "m": "kumite", "en": "KANSA must remain silent if the Referee gives a warning or penalty for passivity during ATO SHIBARAKU.", "es": "KANSA debe permanecer en silencio si el árbitro da una advertencia o penalización por pasividad durante ATO SHIBARAKU.", "a": false}, {"id": "kumite-235", "m": "kumite", "en": "In individual categories with elimination format, a bout can be declared a tie.", "es": "En las categorías individuales con formato de eliminación, un combate puede declararse empate.", "a": false}, {"id": "kumite-236", "m": "kumite", "en": "For all competition formats the Coach will be allowed one video review card for the Athlete.", "es": "Para todos los formatos de competición, se permitirá al entrenador una tarjeta de revisión de video para el atleta.", "a": false}, {"id": "kumite-237", "m": "kumite", "en": "The Athlete can ask the Coach to request a video review discreetely.", "es": "El atleta podrá pedir discretamente al entrenador que solicite una revisión de vídeo.", "a": true}, {"id": "kumite-238", "m": "kumite", "en": "The last six seconds before the bout was stopped for the request will always be evaluated for video review.", "es": "Los últimos six segundos antes de que el combate se detuviera para la solicitud serán siempre evaluados para la revisión por Video.", "a": true}, {"id": "kumite-239", "m": "kumite", "en": "If both Coaches request video review at the same time, the video review Judge can only award the point to whoever is deemed to score first.", "es": "Si ambos entrenadores solicitan la revisión del vídeo al mismo tiempo, el juez de vídeo solo podrá otorgar el punto a quien se considere que ha marcado primero.", "a": false}, {"id": "kumite-240", "m": "kumite", "en": "Simultaneous scoring techniques can be awarded to both Athletes in video review.", "es": "Las técnicas de puntuación simultánea pueden otorgarse a ambos atletas en la revisión por vídeo.", "a": true}, {"id": "kumite-241", "m": "kumite", "en": "The video review Judge cannot overrule any decision made by the Judges, with the exception of SENSHU.", "es": "El juez de revisión de vídeo no podrá anular ninguna decisión de los jueces, con la excepción de SENSHU.", "a": true}, {"id": "kumite-242", "m": "kumite", "en": "The Tatami Manager must supervise that KANSA stops the bout to instruct the Referee regarding a contravention of the Rules of Competition.", "es": "El tatami manager debe supervisar que KANSA detenga el combate para instruir al árbitro sobre una contravención del reglamento de competición.", "a": true}, {"id": "kumite-243", "m": "kumite", "en": "The Referee indicates fouls observed, and imposes warnings and penalties as required by the Rules.", "es": "El árbitro indica las faltas observadas, e impone las advertencias y penalizaciones requeridas por el reglamento.", "a": true}, {"id": "kumite-244", "m": "kumite", "en": "Referee breaks the tie in case of HANTEI.", "es": "El árbitro deshace el empate en caso de HANTEI.", "a": true}, {"id": "kumite-245", "m": "kumite", "en": "In the event that the Referee does not hear the time-up bell, KANSA will blow his whistle.", "es": "En el caso de que el árbitro no oiga la señal de final de tiempo, KANSA hará sonar su silbato.", "a": false}, {"id": "kumite-246", "m": "kumite", "en": "In the Two Judges System, the Judges will assist the Referee by giving signals for JOGAI and excessive contact.", "es": "En el sistema de dos jueces, los jueces asistirán al árbitro dando señales de JOGAI y contacto excesivo.", "a": true}];
